CREATE TABLE "WellnessGiveawayCampaign" ("id" TEXT NOT NULL, "slug" TEXT NOT NULL DEFAULT 'wellness-giveaway', "name" TEXT NOT NULL DEFAULT 'Paw-some Wellness Giveaway', "isPublished" BOOLEAN NOT NULL DEFAULT false, "raffleEnabled" BOOLEAN NOT NULL DEFAULT true, "prizeDescription" TEXT NOT NULL DEFAULT 'A free Wellness Plan Membership', "discountPercent" INTEGER NOT NULL DEFAULT 50, "expiresAt" TIMESTAMP(3), "termsSummary" TEXT NOT NULL DEFAULT 'One entry per email. See full terms for eligibility and restrictions.', "termsContent" TEXT NOT NULL DEFAULT 'Promotion terms will be published before this campaign goes live.', "termsVersion" TEXT NOT NULL DEFAULT 'wellness-giveaway-v1', "winnerEntryId" TEXT, "publishedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "WellnessGiveawayCampaign_pkey" PRIMARY KEY ("id"));
CREATE TABLE "WellnessGiveawayEntry" ("id" TEXT NOT NULL, "campaignId" TEXT NOT NULL, "ownerId" TEXT NOT NULL, "emailHash" TEXT NOT NULL, "currentPatient" BOOLEAN NOT NULL, "marketingOptIn" BOOLEAN NOT NULL DEFAULT false, "marketingConfirmed" BOOLEAN NOT NULL DEFAULT false, "marketingConfirmationSentAt" TIMESTAMP(3), "rewardCode" TEXT NOT NULL, "rewardEmailSentAt" TIMESTAMP(3), "rewardEmailFailedAt" TIMESTAMP(3), "redeemedAt" TIMESTAMP(3), "termsVersion" TEXT NOT NULL, "termsAcceptedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "WellnessGiveawayEntry_pkey" PRIMARY KEY ("id"));
CREATE TABLE "WellnessGiveawayPet" ("id" TEXT NOT NULL, "entryId" TEXT NOT NULL, "petId" TEXT NOT NULL, "name" TEXT NOT NULL, "species" "PetSpecies" NOT NULL, "age" TEXT, "breed" TEXT, CONSTRAINT "WellnessGiveawayPet_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "WellnessGiveawayCampaign_slug_key" ON "WellnessGiveawayCampaign"("slug");
CREATE UNIQUE INDEX "WellnessGiveawayCampaign_winnerEntryId_key" ON "WellnessGiveawayCampaign"("winnerEntryId");
CREATE UNIQUE INDEX "WellnessGiveawayEntry_rewardCode_key" ON "WellnessGiveawayEntry"("rewardCode");
CREATE UNIQUE INDEX "WellnessGiveawayEntry_campaignId_emailHash_key" ON "WellnessGiveawayEntry"("campaignId", "emailHash");
CREATE INDEX "WellnessGiveawayEntry_campaignId_createdAt_idx" ON "WellnessGiveawayEntry"("campaignId", "createdAt");
CREATE INDEX "WellnessGiveawayEntry_ownerId_idx" ON "WellnessGiveawayEntry"("ownerId");
CREATE INDEX "WellnessGiveawayPet_entryId_idx" ON "WellnessGiveawayPet"("entryId");
CREATE INDEX "WellnessGiveawayPet_petId_idx" ON "WellnessGiveawayPet"("petId");
ALTER TABLE "WellnessGiveawayCampaign" ADD CONSTRAINT "WellnessGiveawayCampaign_winnerEntryId_fkey" FOREIGN KEY ("winnerEntryId") REFERENCES "WellnessGiveawayEntry"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "WellnessGiveawayEntry" ADD CONSTRAINT "WellnessGiveawayEntry_campaignId_fkey" FOREIGN KEY ("campaignId") REFERENCES "WellnessGiveawayCampaign"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "WellnessGiveawayEntry" ADD CONSTRAINT "WellnessGiveawayEntry_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "Owner"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "WellnessGiveawayPet" ADD CONSTRAINT "WellnessGiveawayPet_entryId_fkey" FOREIGN KEY ("entryId") REFERENCES "WellnessGiveawayEntry"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "WellnessGiveawayPet" ADD CONSTRAINT "WellnessGiveawayPet_petId_fkey" FOREIGN KEY ("petId") REFERENCES "Pet"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
